// Sanity-render every vendored icon at all three weights to catch bad markup.
let bad = 0;
for (const icon of ICONS.filter((i) => i.provenance)) {
  for (const w of ["light", "regular", "bold"] as const) {
    const svg = iconSvg(icon.id, { weight: w });
    if (!svg || !svg.includes("<svg")) {
      bad++;
      console.log("BAD RENDER", icon.id, w);
    }
  }
}
console.log("bad renders:", bad);

import { findAssets, assetCatalogSummary, ICONS, iconSvg } from "./index";

function top(query: string) {
  const r = findAssets(query, { kind: "icon", limit: 5 });
  return r.map((m) => `${m.id} (score ${m.score})`);
}

